// AdminIdentityServiceServer is the server API for AdminIdentityService service.
// All implementations must embed UnimplementedAdminIdentityServiceServer
// for forward compatibility.
//
// AdminIdentityService is the staff-facing surface (admin-bff): user registry
// browsing, account disabling, and staff/role management.
type AdminIdentityServiceServer interface {
	ListUsers(context.Context, *ListUsersRequest) (*ListUsersResponse, error)
	// SetUserActive soft-disables or re-enables an account (accounts.users.deleted_at).
	SetUserActive(context.Context, *SetUserActiveRequest) (*SetUserActiveResponse, error)
	InviteStaff(context.Context, *InviteStaffRequest) (*InviteStaffResponse, error)
	ListAdminRoles(context.Context, *ListAdminRolesRequest) (*ListAdminRolesResponse, error)
	// HasAdminPermission answers admin RBAC checks (admin.roles/permissions).
	HasAdminPermission(context.Context, *HasAdminPermissionRequest) (*HasAdminPermissionResponse, error)
	// The KYB review queue (admin.verification_queue) belongs to this admin module. It stores ids, region and status
	// only; company details stay with org.
	ListVerificationQueue(context.Context, *ListVerificationQueueRequest) (*ListVerificationQueueResponse, error)
	// ReviewVerification closes the open item and asks org to apply the decision (OrgService.ApplyKybDecision).
	ReviewVerification(context.Context, *ReviewVerificationRequest) (*ReviewVerificationResponse, error)
	// EnqueueVerification opens a review item. Called by org when a company's KYB needs a person; not by admin-bff.
	EnqueueVerification(context.Context, *EnqueueVerificationRequest) (*EnqueueVerificationResponse, error)
	mustEmbedUnimplementedAdminIdentityServiceServer()
}

